/**
 * Decodes a JWT and returns the embedded `user_id`. The signature is not verified.
 *
 * @param token - The JWT to decode.
 * @returns The `user_id` from the token's payload, or an empty string when the token does not have
 *   three dot-separated segments.
 */
export declare function UserFromToken(token: string): string;
/**
 * Creates a development token for `userId`: an unsigned JWT the API accepts only while the app
 * has auth checks disabled (`disable_auth_checks`). Never use one in production.
 *
 * @param userId - The ID of the user the token is for.
 * @returns The development token.
 */
export declare function DevToken(userId: string): string;
